  color: var(--color-secondary);
  text-decoration: underline;
}

/* Forms */
input, textarea, select {
  padding: var(--space-sm);
  border: 1px solid var(--color-muted);
  border-radius: var(--radius-sm);
  font-family: inherit;
  font-size: 16px;
  transition: border-color 0.2s ease;
}

input:focus, textarea:focus, select:focus {
  outline: none;
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px rgba(102, 126, 234, 0.1);
}

/* Cards */
.card {
  background: white;
  border-radius: var(--radius-lg);
  padding: var(--space-lg);
  box-shadow: var(--shadow-md);
  transition: box-shadow 0.2s ease;
}

.card:hover {
  box-shadow: var(--shadow-lg);
}

/* Containers */
.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: var(--space-lg);
}

.container-sm {
  max-width: 800px;
  margin: 0 auto;
  padding: var(--space-lg);
}

/* Grid */
.grid {
  display: grid;
  gap: var(--space-md);
}

.grid-cols-1 { grid-template-columns: 1fr; }
.grid-cols-2 { grid-template-columns: repeat(2, 1fr); }
.grid-cols-3 { grid-template-columns: repeat(3, 1fr); }
.grid-cols-4 { grid-template-columns: repeat(4, 1fr); }

/* Badges */
.badge {
  display: inline-block;
  padding: 4px 8px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 600;
  background: var(--color-muted);
  color: var(--color-dark);
}

.badge-primary {
  background: var(--color-primary);
  color: white;
}

.badge-success {
  background: var(--color-success);
  color: white;
}

.badge-danger {
  background: var(--color-danger);
  color: white;
}

/* Alerts */
.alert {
  padding: var(--space-md);
  border-radius: var(--radius-md);
  margin-bottom: var(--space-md);
  border-left: 4px solid var(--color-primary);
  background: rgba(102, 126, 234, 0.05);
  color: var(--color-dark);
}

.alert-success {
  border-left-color: var(--color-success);
  background: rgba(72, 187, 120, 0.05);
}

.alert-danger {
  border-left-color: var(--color-danger);
  background: rgba(245, 101, 101, 0.05);
}
`
}

// ──────────────────────────────────────────────────────────────────────────
// 반응형 디자인
// ──────────────────────────────────────────────────────────────────────────

func generateResponsiveStyles() -> string {
  return `
/* Mobile First (xs: 320px) */
.grid-cols-1 {
  grid-template-columns: 1fr;
}

/* Small (sm: 640px) */
@media (min-width: 640px) {
  .sm\\:grid-cols-2 {
    grid-template-columns: repeat(2, 1fr);
  }
  .sm\\:px-4 {
    padding-left: 16px;
    padding-right: 16px;
  }
}

/* Medium (md: 768px) */
@media (min-width: 768px) {
  .container {
    padding: 24px;
  }
  .md\\:grid-cols-3 {
    grid-template-columns: repeat(3, 1fr);
  }
  .md\\:text-lg {
    font-size: 18px;
  }
}

/* Large (lg: 1024px) */
@media (min-width: 1024px) {
  .lg\\:grid-cols-4 {
    grid-template-columns: repeat(4, 1fr);
  }
  .lg\\:w-3/4 {
    width: 75%;
  }
}

/* X-Large (xl: 1280px) */
@media (min-width: 1280px) {
  .container {
    max-width: 1280px;
  }
}

/* Dark Mode */
@media (prefers-color-scheme: dark) {
  body {
    background: #1a202c;
    color: #f7fafc;
  }

  .card {
    background: #2d3748;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
  }

  h1, h2, h3, h4, h5, h6 {
    color: #f7fafc;
  }
}
`
}

// ──────────────────────────────────────────────────────────────────────────
// 테마별 CSS 생성
// ──────────────────────────────────────────────────────────────────────────

func generateThemedCSS(themeName: string) -> string {
  let css = \"\"

  if themeName == \"light\" {
    css = `
body {
  background: white;
  color: #1a202c;
}

.card {
  background: #f7fafc;
  border: 1px solid #e2e8f0;
}
`
  }

  if themeName == \"dark\" {
    css = `
body {
  background: #1a202c;
  color: #f7fafc;
}

.card {
  background: #2d3748;
  border: 1px solid #4a5568;
}

h1, h2, h3 {
  color: #f7fafc;
}
`
  }

  if themeName == \"purple\" {
    css = `
:root {
  --color-primary: #667eea;
  --color-secondary: #764ba2;
}

body {
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  color: white;
}
`
  }

  return css
}

// ──────────────────────────────────────────────────────────────────────────
// 통합 CSS 생성
// ──────────────────────────────────────────────────────────────────────────

func generateFullCSS(themeName: string) -> string {
  let css = \"\"

  // 1. CSS Variables
  css = css + generateCSSVariables()
  css = css + \"\\n\\n\"

  // 2. Base Component Styles
  css = css + generateComponentStyles()
  css = css + \"\\n\\n\"

  // 3. Utility Classes
  css = css + generateUtilityClasses()
  css = css + \"\\n\\n\"

  // 4. Responsive Design
  css = css + generateResponsiveStyles()
  css = css + \"\\n\\n\"

  // 5. Theme-specific CSS
  css = css + generateThemedCSS(themeName)

  return css
}

// ──────────────────────────────────────────────────────────────────────────
// 인라인 스타일 생성 (작은 요소용)
