      background: #f9f9f9;
      border-radius: 8px;
      border-left: 4px solid #667eea;
    \"
  `
}

// ──────────────────────────────────────────────────────────────────────────
// Export
// ──────────────────────────────────────────────────────────────────────────

export {
  getThemeColors,
  getThemeSpacing,
  getThemeFonts,
  getThemeBreakpoints,
  generateUtilityClasses,
  generateCSSVariables,
  generateComponentStyles,
  generateResponsiveStyles,
  generateThemedCSS,
  generateFullCSS,
  getInlineHeaderStyles,
  getInlineContainerStyles,
  getInlineCardStyles
}

