/* Min Height */
.min-h-0 { min-height: 0; }
.min-h-full { min-height: 100%; }
.min-h-screen { min-height: 100vh; }
`
}

// ──────────────────────────────────────────────────────────────────────────
// 모든 기본 유틸리티 통합
// ──────────────────────────────────────────────────────────────────────────

func generateAllUtilityClasses() -> string {
  let css = ""
  css = css + generateDisplayClasses()
  css = css + generateSpacingClasses()
  css = css + generateColorClasses()
  css = css + generateTypographyClasses()
  css = css + generateBorderClasses()
  css = css + generateEffectClasses()
  css = css + generateSizeClasses()
  return css
}

// ──────────────────────────────────────────────────────────────────────────
// Export
// ──────────────────────────────────────────────────────────────────────────

export {
  generateDisplayClasses,
  generateSpacingClasses,
  generateColorClasses,
  generateTypographyClasses,
  generateBorderClasses,
  generateEffectClasses,
  generateSizeClasses,
  generateAllUtilityClasses
}

